    {"tool": "send_message", "args": {"to": "infra", "content": "Thanks! Before I run the full eval, could you do a quick quality check on data/test.jsonl? I want to make sure the labels are clean and there are no obvious issues that could skew results. Also let me know if you spot any patterns in the test distribution that we should be aware of."}},
    {"tool": "list_files", "args": {}},
    {"tool": "run_eval", "args": {"dataset_path": "data/test.jsonl", "checkpoint": "ckpt-7"}}
  ],
  "done": false
}
